from lib import *
S = SS('k51')
F1 = [['PV 2Gi / 5Gi / 10Gi', 'RWO,存储类 manual'], ['PVC 请求 3Gi', '→ 5Gi 的那个(最小够用)'], ['20Gi / RWX / 不同存储类', 'Pending'], ['新增 RWX 的 PV', '7.4 秒后自动绑定']]
F2 = [['selector tier=gold', '→ 带该标签的 PV'], ['没有 selector 的 1Gi PVC', '→ 2Gi 的(最小够用)'], ['claimRef 预留', '别的 PVC 拿不走']]
F3 = [['删除 PVC', 'PV → Released(Retain)'], ['新 PVC', 'Pending'], ['去掉 claimRef', '4.5 秒后 Bound'], ['动态供给 Delete', 'PV 随 PVC 一起删']]
F4 = [['PVC dyn', 'Pending: WaitForFirstConsumer'], ['创建用它的 Pod', 'Bound,自动建 PV(带节点亲和)'], ['删 PVC', 'PV 被删(reclaim Delete)']]
PANELS = [('f', 'flow', 'PV 与 PVC 的配对'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("三个静态 PV(存储类 manual,RWO):2Gi、5Gi、10Gi。PVC c3g 请求 3Gi → 绑定到 5Gi 的 k51-pv-5g(最小的、够用的);请求 20Gi 的 c20g、请求 ReadWriteMany 的 crwx(现有 PV 都只有 RWO)、storageClassName 是 other 的 cclass 都保持 Pending。新增一个 RWX 的 PV 之后 7.4 秒,Pending 的 crwx 自动绑定到它(PV 控制器是周期性同步的)。", f=fl(F1, cur=[1], mark=[2], done=[3]), t=tl(S(1), mark=lidx(S(1), 'c3g', 'c20g', 'crwx', 'cclass'), done=lidx(S(1), '现在加一个 RWX')), kv=KV([['配对条件', '容量够、访问模式够、存储类相同、selector 匹配'], ['多个候选', '选容量最小的'], ['Pending', '没有匹配的 PV 时一直等,PV 出现后自动绑定']], ['配对条件'])),
    step("标签选择器:PVC want-gold(selector tier=gold)绑定到带 tier=gold 的 PV;没有 selector、请求 1Gi 的 plain-small 绑定到 2Gi 的 PV(最小够用)。预留:PV k51-pv-reserved 预先写了 claimRef(只给 k51/reserved-for-me),集群里没有别的可用 PV 时,另一个 PVC someone-else 保持 Pending(PV 显示 Available→reserved-for-me);reserved-for-me 创建后 Bound 到它。", f=fl(F2, cur=[0, 1], done=[2]), t=tl(S(2), mark=lidx(S(2), 'want-gold', 'someone-else'), done=lidx(S(2), 'plain-small', 'reserved-for-me')), kv=KV([['selector', '只选带这些标签的 PV'], ['claimRef', '预先绑定:PV 只给指定的 PVC'], ['静态预留', '用来把特定 PV 留给特定的人']], ['claimRef'])),
    step("删除 PVC 之后,reclaimPolicy: Retain 的静态 PV 变成 Released,spec.claimRef 还指着已经删除的 PVC c1(数据和绑定记录都保留);新建 PVC c2 保持 Pending——Released 的 PV 不会被别人拿去用;手动去掉 PV 的 claimRef 之后 4.5 秒 c2 绑定成功。对照:动态供给的 StorageClass standard 是 reclaimPolicy=Delete,删除 PVC 后 PV 随之被删除。", f=fl(F3, cur=[0, 1], done=[2, 3]), t=tl(S(3), mark=lidx(S(3), 'Released', '新建 PVC c2'), done=lidx(S(3), '手动去掉 PV 的 claimRef')), kv=KV([['Retain', '删 PVC 后 PV 变 Released,留给人工处理'], ['Delete', 'PV 和底层数据一起删(动态供给默认)'], ['Released → 再次可用', '要先清掉 claimRef']], ['Retain'])),
    step("动态供给与 WaitForFirstConsumer:standard 的 volumeBindingMode=WaitForFirstConsumer、provisioner=rancher.io/local-path。PVC dyn 创建后保持 Pending,事件 WaitForFirstConsumer: waiting for first consumer to be created before binding;创建用它的 Pod 之后 dyn 变成 Bound,自动创建了 PV(带节点亲和,落在 kx-sched-worker3);删除 PVC 后这个 PV 被删除。", f=fl(F4, cur=[1], done=[0, 2]), t=tl(S(4), mark=lidx(S(4), 'WaitForFirstConsumer', '创建用它的 Pod'), done=lidx(S(4), '删除 PVC dyn')), kv=KV([['WaitForFirstConsumer', '等有 Pod 使用才供给,让卷和 Pod 在同一个节点'], ['本地卷', '自动带节点亲和,Pod 只能调度到那个节点'], ['Immediate', '另一种模式:PVC 创建就立即供给']], ['WaitForFirstConsumer'])),
]
A = mkartk('k51', 51, 'Kubernetes,PV,PVC,存储绑定,reclaimPolicy,WaitForFirstConsumer,真实验证,动画演示',
    '在 kind 集群里实测 PV 与 PVC 的配对:3Gi 的 PVC 在 2Gi/5Gi/10Gi 三个 PV 里选最小够用的 5Gi;20Gi、RWX 或存储类不同的 PVC 保持 Pending,新增匹配的 PV 后 7.4 秒自动绑定;selector 选标签、claimRef 预留给指定 PVC;Retain 的 PV 在删除 PVC 后变 Released 且不会被别人拿走,去掉 claimRef 后 4.5 秒可再次绑定;动态供给的 standard 是 WaitForFirstConsumer、reclaimPolicy Delete,PV 随 PVC 一起被删除。',
    'PVC 是怎么找到 PV 的?为什么有的 PVC 一直 Pending?PVC 删了数据去哪了?这篇先用手工建的静态 PV 把配对规则逐条验证,再看动态供给的 WaitForFirstConsumer 和 Delete 回收策略。',
    [('5Gi', '请求 3Gi 的 PVC 在 2Gi、5Gi、10Gi 三个 PV 里被绑定的那个(最小够用)'), ('Released', 'reclaimPolicy: Retain 的 PV 在 PVC 删除后的状态:claimRef 还在,别人拿不走'), ('WaitForFirstConsumer', '动态供给的 PVC 在没有 Pod 使用时的事件:waiting for first consumer')],
    [('配对规则', '<p>PV 控制器把 PVC 和 PV 配对看四件事:容量够、访问模式够、<code>storageClassName</code> 相同、(如果写了)<code>selector</code> 匹配。三个 PV 2Gi/5Gi/10Gi,请求 3Gi 的 PVC 拿到 5Gi 的——候选里最小的。请求 20Gi、<code>ReadWriteMany</code>(现有 PV 只有 RWO)或不同存储类的 PVC 都保持 <code>Pending</code>;新增一个匹配的 PV 之后 7.4 秒,Pending 的 PVC 自动绑上去(PV 控制器是周期性同步的)。</p>'),
     ('selector 与预留', '<p>PVC 的 <code>selector.matchLabels</code> 只选带这些标签的 PV(<code>tier=gold</code> 的那个);没有 selector 的 1Gi PVC 拿了 2Gi 的最小 PV。PV 上可以预先写 <code>claimRef</code>,把它只留给指定的 PVC:集群里别的 PV 都用掉后,另一个 PVC 想要它,保持 Pending;预留的 PVC 一创建就绑定。</p>'),
     ('删除之后', '<p><code>persistentVolumeReclaimPolicy: Retain</code> 的静态 PV,删掉 PVC 后变成 <code>Released</code>,<code>spec.claimRef</code> 还指着已不存在的 PVC——数据和绑定记录都保留,新 PVC 拿不走它(c2 一直 Pending)。要重新使用得手动把 <code>claimRef</code> 去掉,4.5 秒后 c2 就绑定了。动态供给的 StorageClass 默认是 <code>Delete</code>:PVC 一删,PV 和底层数据都没了。</p>'),
     ('动态供给', '<p>kind 的 <code>standard</code> 存储类用 <code>rancher.io/local-path</code>、<code>volumeBindingMode: WaitForFirstConsumer</code>:PVC 创建后保持 <code>Pending</code>,事件 <code>waiting for first consumer to be created before binding</code>;创建了使用它的 Pod 之后才供给——自动建出的 PV 带节点亲和,落在 Pod 被调度到的那个节点上(worker3);之后 Pod 只能回到这个节点。删除 PVC,PV 随之被删除(<code>reclaimPolicy: Delete</code>)。</p>')],
    steps,
    [ENV_K + '。独立的 5 节点 kind 集群 kx-sched(Kubernetes v1.37.0);静态 PV 用 hostPath(/tmp/<名字>,节点内),storageClassName 写的是 manual(集群里并没有这个 StorageClass 对象,PVC 的事件因此是 storageclass … "manual" not found,但静态绑定不受影响);动态供给用 kind 自带的 standard(local-path-provisioner);第 1 节新增 PV 后的绑定延迟与第 3 节去掉 claimRef 后的绑定延迟取自 0.5 秒间隔轮询(另一次运行里 4 秒还没绑定,所以不要假设是即时的);实验后删除了所有 PV 与命名空间;每种情形各一次',
     '没有验证:Block 模式卷;PV 的 nodeAffinity 与调度;volumeName 预绑定(PVC 直接指定 PV);PV/PVC 保护 finalizer 与删除顺序(见 Finalizer 一篇);存储类的 allowVolumeExpansion(下一篇之后);跨 StorageClass 的默认存储类(没有写 storageClassName 时使用默认类);CSI 驱动的供给流程'],
    'PV 与 PVC 的配对', PANELS)
